head.script:
let objParent = $p.parent();



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[common > E > oneditkeyup]<br/>키보드에서 키를 눌렀다 놓았을 때 발생합니다.",
    "validation" : [
        "",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // comp 생성 호출
    objParent.scwin.comp_init();
}



objParent.scwin.target1_oneditkeyup = function (info, e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oneditkeyup 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.keyCode : " + info.keyCode);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
}
